# SCHED-GAP-1660 — Board-write nudge stamp leaking cooldown lanes

**Class:** go-scheduler-board-write-nudge-cooldown-leak
**Repo:** coding-hermes/scheduler · v1.9.x · Go 1.26 · sqlite
**Symptom:** 123/402 admissions (31%) on cooldown-mode lanes were attributed to a nudge (`resume:board_wake` 75, `resume:startup` 47, `resume:manual` 1) rather than cooldown expiry, with 96 rows blank.

## 1. Root cause

A single **process-wide** `nudge_source` stamp (set by `BoardWakeWatcher` to `board_wake`) is consumed by whichever lane spawns next, with no per-lane gate:

```
BoardWakeWatcher ──set nudge_source=board_wake──▶ SlotPool.spawn
                                                     │
                                      admit_reason = "resume:"+nudgeSource
                                      (whenever nudgeSource != "")
                                                     │
                                       whichever lane happens to spawn next
```

1. **A cooldown lane consumes a stamp it did not earn** — `spawn` never re-derives `last_admit + cooldown` for the lane it is admitting.
2. **The one legitimate wake-driven admission is unmeasurable** — any admission while a stamp is set is labelled `resume:board_wake`; no persisted state distinguishes a genuine park→flip.
3. **Not every path stamps a reason** — 96 blank rows, including the sim spawn path.

Failure class: *a process-wide signal consumed by whichever lane spawns next, with no per-lane gate between stamp and admission.*

## 2. Exact fix

### 2.1 Clock seam (only permitted `time.Now`)

`internal/clock/clock.go`:

```go
package clock

import "time"

type Clock interface{ Now() time.Time }

type realClock struct{}

// The single permitted call to time.Now in the whole module.
func (realClock) Now() time.Time { return time.Now() }

func Real() Clock { return realClock{} }

type Fake struct{ t time.Time }

func NewFake(t time.Time) *Fake         { return &Fake{t: t} }
func (f *Fake) Now() time.Time          { return f.t }
func (f *Fake) Advance(d time.Duration) { f.t = f.t.Add(d) }
func (f *Fake) Set(t time.Time)         { f.t = t }
```

Build gate:

```make
verify-clock:
	@! grep -rn --include='*.go' 'time\.Now()' . \
		| grep -v 'internal/clock/' | grep -v '_test.go' | grep . \
	&& echo "clock seam OK"
```

### 2.2 Per-lane park mark (persisted)

`migrations/0007_lane_park_marks.sql`:

```sql
CREATE TABLE IF NOT EXISTS lane_park_marks (
    lane_id    TEXT PRIMARY KEY,
    parked_at  INTEGER NOT NULL,  -- clock seam, unix millis
    reason     TEXT    NOT NULL,  -- 'board_empty'
    board_rev  INTEGER NOT NULL
);

UPDATE ticks SET admit_reason = 'ok'
 WHERE admit_reason IS NULL OR admit_reason = '';
```

`internal/sched/park.go`:

```go
type ParkMark struct {
	LaneID   string
	ParkedAt time.Time
	Reason   string
	BoardRev int64
}

type ParkStore interface {
	Record(ctx context.Context, m ParkMark) error
	Get(ctx context.Context, laneID string) (ParkMark, bool, error)
	Clear(ctx context.Context, laneID string) error
}
```

Derive-and-record at the admission-deferral board read; perpetual/`NEVER-DONE` rows excluded:

```go
func (p *SlotPool) boardReadForAdmission(ctx context.Context, lane *Lane) (bool, error) {
	rows, err := p.board.ReadDispatchable(ctx, lane.Selector)
	if err != nil {
		return false, err
	}
	rows = excludePerpetual(rows) // drops NEVER-DONE / perpetual rows

	if len(rows) > 0 {
		if err := p.park.Clear(ctx, lane.ID); err != nil {
			return false, err
		}
		return true, nil
	}
	if lane.Mode == LaneModeTasks {
		if err := p.park.Record(ctx, ParkMark{
			LaneID: lane.ID, ParkedAt: p.clock.Now(),
			Reason: "board_empty", BoardRev: p.board.Revision(),
		}); err != nil {
			return false, err
		}
	}
	return false, nil
}
```

### 2.3 Per-lane admission gate

```go
type LaneMode int

const (
	LaneModeCooldown LaneMode = iota // admission only on cooldown expiry
	LaneModeTasks
)

type admitDecision struct {
	Admit       bool
	AdmitReason string
	consumePark bool
}

func (p *SlotPool) decide(ctx context.Context, lane *Lane, now time.Time) (admitDecision, error) {
	switch lane.Mode {
	case LaneModeCooldown:
		if now.Before(lane.LastAdmit.Add(lane.Cooldown)) {
			// STRUCTURAL REFUSAL: never admitted by a nudge.
			return admitDecision{Admit: false, AdmitReason: "cooldown"}, nil
		}
		return admitDecision{Admit: true, AdmitReason: "cooldown_expired"}, nil

	case LaneModeTasks:
		_, parked, err := p.park.Get(ctx, lane.ID)
		if err != nil {
			return admitDecision{}, err
		}
		// ONE sanctioned flip: parked + board write. A bare board_wake with no
		// park mark is resume, not flip.
		if parked && p.nudge == NudgeBoardWake {
			return admitDecision{Admit: true, AdmitReason: "flip:board_wake", consumePark: true}, nil
		}
		if p.nudge != NudgeNone {
			return admitDecision{Admit: true, AdmitReason: "resume:" + string(p.nudge)}, nil
		}
		return admitDecision{Admit: true, AdmitReason: "ok"}, nil
	}
	return admitDecision{Admit: false, AdmitReason: "unknown_lane_mode"}, nil
}
```

```go
func (p *SlotPool) spawn(ctx context.Context, lane *Lane) error {
	now := p.clock.Now()
	d, err := p.decide(ctx, lane, now)
	if err != nil {
		return err
	}
	if !d.Admit {
		return p.recordTick(ctx, lane, d, now)
	}
	if d.consumePark {
		if err := p.park.Clear(ctx, lane.ID); err != nil {
			return err
		}
	}
	lane.LastAdmit = now
	if err := p.recordTick(ctx, lane, d, now); err != nil {
		return err
	}
	return p.admit(ctx, lane)
}
```

### 2.4 Wrapper hook drops the stamp when only cooldown lanes could be served

```go
func (p *SlotPool) onBoardWrite(ctx context.Context, ev BoardWriteEvent) error {
	now := p.clock.Now()
	admittableByWake := false
	for _, lane := range p.candidateLanes(ev) {
		if lane.Mode == LaneModeTasks {
			admittableByWake = true
			break
		}
		// cooldown lane: never the reason a wake stamp exists, elapsed or not
	}
	if !admittableByWake {
		p.clearNudgeIf(NudgeBoardWake) // no orphan stamp for the next lane
		return nil
	}
	p.setNudge(NudgeBoardWake)
	return nil
}
```

### 2.5 Stamp `admit_reason` on every path incl. sim

```go
const AdmitReasonOK = "ok"

func (p *SlotPool) recordTick(ctx context.Context, lane *Lane, d admitDecision, now time.Time) error {
	reason := d.AdmitReason
	if reason == "" {
		reason = AdmitReasonOK
	}
	_, err := p.db.ExecContext(ctx,
		`INSERT INTO ticks(lane_id, admitted, admit_reason, ts) VALUES(?,?,?,?)`,
		lane.ID, d.Admit, reason, now.UnixMilli())
	return err
}

func (p *SlotPool) simSpawn(ctx context.Context, lane *Lane) error { return p.spawn(ctx, lane) }
```

```sql
-- migrations/0008_admit_reason_not_blank.sql
CREATE TRIGGER IF NOT EXISTS ticks_admit_reason_not_blank
BEFORE INSERT ON ticks
WHEN NEW.admit_reason IS NULL OR NEW.admit_reason = ''
BEGIN
    SELECT RAISE(ABORT, 'admit_reason must be non-empty (SCHED-GAP-1660)');
END;
```

## 3. Verification

### 3.1 Baseline reproduction

```sql
SELECT admit_reason, COUNT(*) AS n FROM ticks
 WHERE ts >= :seven_days_ago GROUP BY admit_reason ORDER BY n DESC;
-- ok 183, '' 96, resume:board_wake 75, resume:startup 47, resume:manual 1
```

### 3.2 Acceptance tests (`clock.Fake` only)

```go
// 7-day simulated board writes on a 72h cooldown lane produce zero board_wake rows.
func TestCooldownLaneIgnoresBoardWakeFor7Days(t *testing.T) {
	clk := clock.NewFake(time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC))
	pool, lane := newTestPool(t, clk, LaneSpec{ID: "cooldown-72h", Mode: LaneModeCooldown, Cooldown: 72 * time.Hour})
	for d := 0; d < 7; d++ {
		for i := 0; i < 8; i++ {
			require.NoError(t, pool.onBoardWrite(ctx, BoardWriteEvent{Lane: lane.ID}))
			require.NoError(t, pool.spawn(ctx, lane))
			clk.Advance(3 * time.Hour)
		}
	}
	var n int
	require.NoError(t, pool.db.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM ticks WHERE lane_id=? AND admit_reason LIKE '%board_wake%'`, lane.ID).Scan(&n))
	require.Zero(t, n)
	require.NoError(t, pool.db.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM ticks WHERE lane_id=? AND admitted=1 AND admit_reason='cooldown_expired'`, lane.ID).Scan(&n))
	require.Equal(t, 2, n) // 168h / 72h
}

// Park / flip / perpetual-only: empty board parks; board write consumes mark -> exactly
// one flip:board_wake; board_wake with no mark -> resume:board_wake; perpetual-only -> parked, 0 flips.
