// Restart does not admit inside cooldown.
func TestRestartDoesNotAdmitInsideCooldown(t *testing.T) { /* reopen store, advance <72h -> cooldown */ }

// Stamp coverage across normal/deferred/cooldown/startup/manual/sim paths.
func TestAdmitReasonStampCoverage(t *testing.T) {
	var n int
	require.NoError(t, db.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM ticks WHERE admit_reason IS NULL OR admit_reason=''`).Scan(&n))
	require.Zero(t, n)
}
```

### 3.3 Post-fix queries

```sql
SELECT COUNT(*) FROM ticks WHERE lane_id='cooldown-72h' AND admit_reason LIKE 'resume:board_wake'; -- 0
SELECT admit_reason, COUNT(*) FROM ticks WHERE ts >= :seven_days_ago GROUP BY 1 ORDER BY 2 DESC;
SELECT admit_reason, COUNT(*) FROM ticks WHERE admit_reason IN ('flip:board_wake','resume:board_wake') GROUP BY 1;
```

